function esc(s) { return String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
function pagina(titulo, corpo) {
  return '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' + esc(titulo) + '</title>'
    + '<style>body{font-family:system-ui,sans-serif;max-width:480px;margin:24px auto;padding:0 16px;color:#1f2a2e;background:#f7f5f0}'
    + '.box{background:#fff;border:1px solid #ddd;border-radius:12px;padding:16px;white-space:pre-wrap;line-height:1.5}'
    + 'button{width:100%;margin-top:16px;padding:14px;font-size:17px;border:0;border-radius:10px;background:#1f6f5c;color:#fff}'
    + 'p.m{color:#666;font-size:14px}</style></head><body><h2>' + esc(titulo) + '</h2>' + corpo + '</body></html>';
}
function validar(lead, token) {
  const wf = ((lead && lead.custom_fields) || {}).wf01 || {};
  const p = wf.msg_b_pendente || null;
  if (!lead || !lead.id) return { ok: false, motivo: 'Lead não encontrado.' };
  if (!p || !p.token || p.token !== token) return { ok: false, motivo: 'Link inválido ou já substituído.' };
  if (wf.robo_resposta_enviada_em) return { ok: false, motivo: 'Essa mensagem já foi enviada em ' + new Date(wf.robo_resposta_enviada_em).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' }) + '.' };
  if (p.criado_em && (Date.now() - new Date(p.criado_em).getTime()) > 72 * 3600 * 1000) return { ok: false, motivo: 'Link vencido (mais de 72 horas).' };
  return { ok: true, p };
}
const q = $('Abrir Link (GET)').first().json.query || {};
const lead = $input.first().json;
const v = validar(lead, String(q.t || ''));
let html;
if (!v.ok) {
  html = pagina('Não dá pra enviar', '<p>' + esc(v.motivo) + '</p>');
} else {
  html = pagina('Enviar pelo 2144?', '<p class="m">Para: ' + esc(v.p.empresa || v.p.telefone) + '</p><div class="box">' + esc(v.p.texto) + '</div>'
    + '<form method="POST"><input type="hidden" name="lead" value="' + esc(lead.id) + '"><input type="hidden" name="t" value="' + esc(q.t) + '">'
    + '<button type="submit">Enviar mensagem</button></form>'
    + '<p class="m">Sai pelo mesmo número do primeiro contato e fica registrada no CRM.</p>');
}
return [{ json: { html } }];

