  + '<h2>Mensagem enviada ✅</h2><div class="box">' + esc(v.p.texto) + '</div><p class="m">Enviada pelo 2144 para ' + esc(v.p.empresa || v.p.telefone) + ' e registrada no CRM.</p></body></html>';
return [{ json: { lead_id: v.lead_id, patch_body: JSON.stringify({ custom_fields: Object.assign({}, cf, { wf01 }) }), html } }];
